            return json_success(json.dumps(tab_state_id))
        except Exception as ex:  # pylint: disable=broad-except
            db.session.rollback()
            return json_error_response(error_msg_from_exception(ex), 400)", "commentary": "migrate_query checks ownership of tab_state_id but updates Query by client_id only, with no user_id filter, so any user's query with that client_id is reassigned.", "end_line": 182, "file_path": "superset/views/sql_lab/views.py", "start_line": 164}, {"code": "    @has_access_api
